    /// <summary>
    /// Provides methods for binding hyperlinks to GUI text blocks and joining enumerable items to rich strings.
    /// </summary>
    /// <remarks>
    /// Contains extension methods for creating rich text strings with clickable hyperlinks and for binding
    /// those hyperlinks to GUI components's click areas.
    /// </remarks>
    public static class HyperlinkExtensions
    {
        /// <summary>
        /// Joins an enumerable of items into a single <see cref="RichString"/>, applying color formatting to each item.
        /// </summary>
        /// <typeparam name="T">The type of items in the enumerable.</typeparam>
        /// <param name="items">The items to join.</param>
        /// <param name="separator">The separator string between items.</param>
        /// <param name="textSelector">A function that selects the text for each item.</param>
        /// <param name="colorSelector">A function that selects the color for each item.</param>
        /// <returns>A <see cref="RichString"/> containing all items with color formatting applied.</returns>
        /// <remarks>
        /// Each item's text is formatted with its corresponding color using the <c>RichString.SetColor(string)</c>
        /// pattern. The ‖ symbol is used as the RichText color tag delimiter. The original ‖ characters in the text
        /// are removed (replaced with empty string) to avoid breaking the RichText parser.
        /// </remarks>
        public static RichString JoinToRichString<T>(
                    this IEnumerable<T> items,
                    string separator,
                    Func<T, string> textSelector,
                    Func<T, Color> colorSelector)
        {
            var sb = new System.Text.StringBuilder();
            var list = items.ToList();

            for (int i = 0; i < list.Count; i++)
            {
                var item = list[i];
                Color color = colorSelector(item);
                string text = textSelector(item).Replace("‖", "");

                // Formateo simple por color.
                sb.Append(text.SetColor(color));

                if (i < list.Count - 1) sb.Append(separator);
            }

            return RichString.Rich(sb.ToString());
        }

        /// <summary>
        /// Binds clickable hyperlinks to a <see cref="GUITextBlock"/> from an enumerable of items.
        /// </summary>
        /// <typeparam name="T">The type of items.</typeparam>
        /// <param name="textBlock">The text block to which click areas will be added.</param>
        /// <param name="items">The items to bind hyperlinks for.</param>
        /// <param name="onPrimaryClick">The action to invoke when a hyperlink is primary-clicked.</param>
        /// <param name="onSecondaryClick">Optional action to invoke when a hyperlink is secondary-clicked.</param>
        /// <remarks>
        /// The method iterates over the RichTextData of the text block and adds clickable areas corresponding to
        /// each item. Clickable areas store the data and invoke the appropriate click handlers. If
        /// <paramref name="onSecondaryClick"/> is not provided, secondary clicks are ignored.
        /// </remarks>
        public static void BindHyperlinks<T>(
                    this GUITextBlock textBlock,
                    IEnumerable<T> items,
                    Action<T> onPrimaryClick,
                    Action<T>? onSecondaryClick = null)
        {
            var list = items.ToList();

            void ApplyLinks()
            {
                if (textBlock.RichTextData == null) return;
                textBlock.ClickableAreas.Clear();

                int index = 0;
                foreach (var data in textBlock.RichTextData)
                {
                    if (data.StartIndex >= data.EndIndex || data.StartIndex < 0 || data.Color == null) continue;
                    if (index >= list.Count) break;

                    var target = list[index];
                    textBlock.ClickableAreas.Add(new GUITextBlock.ClickableArea()
                    {
                        Data = data,
                        OnClick = (tb, area) => { onPrimaryClick?.Invoke(target); },
                        OnSecondaryClick = onSecondaryClick != null ? ((tb, area) => { onSecondaryClick.Invoke(target); }) : null
                    });
                    index++;
                }
            }

            ApplyLinks();
            textBlock.RectTransform.SizeChanged += ApplyLinks;
        }
    }

