    /// <summary>
    /// Provides syntax highlighting for XML code strings, coloring nodes, attributes, values, comments, and punctuation.
    /// </summary>
    /// <remarks>
    /// Uses regular expressions to identify and color different parts of XML syntax. The coloring follows a "Dark Theme"
    /// style palette. Note that color tags (‖color:...‖) are protected from being replaced by the punctuation regex.
    /// </remarks>
    public static partial class XMLHighlighter
    {
        // Syntax colors (IDE "Dark Theme" style palette)
        private static readonly Color ColNode = Color.CornflowerBlue;   // <Item>
        private static readonly Color ColAttr = Color.LightSkyBlue;     // identifier=
        private static readonly Color ColValue = Color.LightSalmon;     // "steel"
        private static readonly Color ColComment = Color.DarkSeaGreen;  // <!-- comment -->
        private static readonly Color ColPunctuation = Color.LightGray; // < > / =

        /// <summary>
        /// Formats an XML string with syntax highlighting colors.
        /// </summary>
        /// <param name="rawXml">The raw XML string to format. If null or whitespace, returns an empty RichString.</param>
        /// <returns>A <see cref="RichString"/> with syntax highlighting colors applied.</returns>
        /// <remarks>
        /// The formatting performs the following steps:
        /// 1. Escapes the ‖ RichText character to || to avoid parser conflicts.
        /// 2. Highlights string values (text between quotes) using the ColValue color.
        /// 3. Highlights attributes (identifier=) using the ColAttr color.
        /// 4. Highlights node names (&lt;Node&gt;) using the ColNode color.
        /// 5. Highlights punctuation (&lt; &gt; / =) using the ColPunctuation color.
        ///     - Note: To avoid replacing our own color tags (‖color:Hex‖), the regex will not touch anything between ‖ symbols.
        /// 6. Highlights comments (&lt;!-- ... --&gt;) using the ColComment color, overwriting any internal colors.
        /// 
        /// The coloring uses a "Dark Theme" style palette defined as private static readonly fields:
        /// - ColNode: CornflowerBlue (for node names)
        /// - ColAttr: LightSkyBlue (for attributes)
        /// - ColValue: LightSalmon (for string values)
        /// - ColComment: DarkSeaGreen (for comments)
        /// - ColPunctuation: LightGray (for punctuation)
        /// 
        /// Example usage:
        /// <code>
        /// var formatted = XMLHighlighter.FormatToXMLCode("&lt;Item identifier=\"test\"&gt;value&lt;/Item&gt;");
        /// </code>
        /// </remarks>
        public static RichString FormatToXMLCode(this string rawXml)
        {
            if (string.IsNullOrWhiteSpace(rawXml)) return RichString.Rich("");

            // 1. Scape Barotrauma RichText characters (the ‖ symbol)
            // If the raw XML had this symbol for some reason, it would break the parser.
            string safeXml = rawXml.Replace("‖", "||");

            // 2. Highlight Strings (Values between quotes)
            safeXml = RegexValue().Replace(safeXml, match
                => match.Value.SetColor(ColValue));

            // 3. Highlight Attributes
            safeXml = RegexAttribute().Replace(safeXml, match
                => match.Value.SetColor(ColAttr));

            // 4. Highlight Node Names (<Node)
            safeXml = RegexNodeName().Replace(safeXml, match
                => match.Value.SetColor(ColNode));

            // 5. Highlight Punctuation (Angles and equals signs)
            // NOTE: To avoid replacing our own color tags (‖color:Hex‖), 
            // the regex will not touch anything between ‖ symbols.
            // A safer way is to do punctuation first, but it interferes with HTML.
            // To simplify, we color the basic punctuation.
            safeXml = RegexPunctuation().Replace(safeXml, match
                => match.Value.SetColor(ColPunctuation));

            // 6. Highlight Comments (They have priority and overwrite any internal color)
            safeXml = RegexComment().Replace(safeXml, match
                => CleanComment().Replace(match.Value, "").SetColor(ColComment));

            return safeXml.Rich();
        }

