    /// Provides extension methods for <see cref="IEnumerable{T}"/>.
    /// </summary>
    /// <remarks>
    /// Currently provides a method to join items into a CSV string.
    /// </remarks>
    public static class IEnumerableExt
    {
        /// <summary>
        /// Joins the elements of a collection into a comma-separated string.
        /// </summary>
        /// <typeparam name="T">The type of elements in the collection.</typeparam>
        /// <param name="collection">The collection to join.</param>
        /// <param name="separator">The separator character to use. Defaults to ','.</param>
        /// <returns>A string containing all elements joined by the separator.</returns>
        /// <remarks>
        /// Uses <c>string.Join(char, IEnumerable{object})</c> internally. Each element's ToString()
        /// method is called to get its string representation.
        /// </remarks>
        public static string ToCsv<T>(this IEnumerable<T> collection, char separator = ',')
        {
            return string.Join(separator, collection);
        }
    }

    /// <summary>
    /// Provides extension methods for <see cref="IDictionary{TKey, TValue}"/>.
    /// </summary>
    /// <remarks>
    /// Currently provides a thread-safe method to get a value by key.
    /// </remarks>
    public static class IDictionaryExt
    {
        /// <summary>
        /// Gets a value from a dictionary in a thread-safe manner.
        /// </summary>
        /// <typeparam name="S">The key type. Must not be null.</typeparam>
        /// <typeparam name="T">The value type.</typeparam>
        /// <param name="dict">The dictionary to look up the value in.</param>
        /// <param name="key">The key to look up.</param>
        /// <returns>The value associated with the key, or the default value for <typeparamref name="T"/> if not found.</returns>
        /// <remarks>
        /// Acquires a lock on the dictionary before performing the lookup, ensuring thread safety
        /// when multiple threads access the same dictionary.
        /// </remarks>
        public static T? GetValueLocked<S, T>(this IDictionary<S, T> dict, S key) where S : notnull
        {
            lock (dict)
                if (dict.TryGetValue(key, out var value))
                    return value;
            return default;
        }
    }

    /// <summary>
    /// Provides extension methods for <see cref="ISettingBase{T}"/> and <see cref="ISettingControl"/>.
    /// </summary>
    /// <remarks>
    /// Provides a SetIfNotEqual method that only sets the value if it's different from the current value,
    /// preventing unnecessary change events and saves.
    /// </remarks>
    public static class ISettingBaseExt
    {
        /// <summary>
        /// Sets the setting value only if it differs from the current value.
        /// </summary>
        /// <typeparam name="T">The setting value type. Must implement <see cref="IEquatable{T}"/> and <see cref="IConvertible"/>.</typeparam>
        /// <param name="setting">The setting to update.</param>
        /// <param name="value">The new value to set.</param>
        /// <returns><c>true</c> if the value was changed; <c>false</c> if the value was already equal to the current value.</returns>
        /// <remarks>
        /// Uses <see cref="IEquatable{T}.Equals(T)"/> to compare the current value with the new value.
        /// Only calls <see cref="ISettingBase{T}.TrySetValue(T)"/> if the values differ.
        /// </remarks>
        public static bool SetIfNotEqual<T>([NotNullWhen(false)] this ISettingBase<T> setting, T value) where T : IEquatable<T>, IConvertible
                    => (!setting.Value?.Equals(value) ?? true) && setting.TrySetValue(value);

        /// <summary>
        /// Sets the key or mouse binding only if it differs from the current value.
        /// </summary>
        /// <param name="setting">The setting to update.</param>
        /// <param name="value">The new key or mouse value to set.</param>
        /// <returns><c>true</c> if the value was changed; <c>false</c> if the value was already equal to the current value.</returns>
        /// <remarks>
        /// Uses <see cref="IEquatable{T}.Equals(T)"/> to compare the current value with the new value.
        /// Only calls <see cref="ISettingControl.TrySetValue(KeyOrMouse)"/> if the values differ.
        /// </remarks>
        public static bool SetIfNotEqual([NotNullWhen(false)] this ISettingControl setting, KeyOrMouse value)
                    => (!setting.Value?.Equals(value) ?? true) && setting.TrySetValue(value);
    }
}